    "overview": "Et avslappende og rolig opphold på et mentalsykehus er bedre enn å sitte bak lås og slå. Det mener nå småforbryteren Randle P. McMurphy. Han spiller sinnssyk såpass overbevisende at han blir lagt inn blant \"tullingene\" som han velger å kalle sine medpasienter. Randle reagerer på de faste og strenge rutinene innenfor mentalsykehusets vegger. Kan det være riktig at voksne menn skal dopes ned på beroligende midler og subbe rundt i morgenkåper istedenfor å få se på sport på TV? Det er ikke måten å behandle mentalpasienter på mener Randle. Det blir umiddelbar konflikt mellom den livslystige og rappkjeftede Randle og hans strikse og kjølige sykesøster. Men Randle lever farlig. På sykehus for sinnsslidende har man sine metoder for å ta seg av vanskelige pasienter. \"Ferieoppholdet\" kan fort bli lengre enn man har beregnet.",
