    "overview": "Hvordan finne lys, glede og mening med livet etter at den verst tenkelige tragedie rammer? For åtte år siden, midt på lyse dagen, blir barnevognen med lille Isak fjernet utenfor en kafé. Noen minutter senere blir han borte i vannmassene i en elv rett i nærheten, og siden aldri funnet.  Etter stor suksess med filmene Schpaaa og Hawaii, Oslo kommer nå Erik Poppes tredje film. deUSYNLIGE står, i likhet med sine to forgjengere, usedvanlig godt på egne ben. I tillegg til et vilt, vakkert og vart filmspråk signert Poppe, er det ting som knytter dem til hverandre. Felles for alle tre er at de tør å ta tak i De Store Temaene og De Store Følelsene - på en positiv måte. Det handler om meningen med livet. Og i deUSYNLIGE også om meningen med døden.",
