    "awards": [],
    "overview": "Etter et langt og innholdsrikt liv havner Allan Karlson på et gamlehjem i den tro at det vil bli hans siste stopp. Problemet er at helsen hans fortsatt er utmerket og dagene blir derfor veldig kjedelige.  Når feiringen av Allans 100-års dag nærmer seg, noe Allan ikke er det minste interessert i, benytter han sjansen og rømmer fra sitt kjedelige liv. En serie av hendelser tar i stedet Allan med på en ellevill og uventet reise omgitt av en gjeng kriminelle, mordere, en pose full av penger, en elefant og et inkompetent politi. For alle andre ville dette ha vært et eventyr for livet, men med Allans bakgrunn er det omtrent som vanlig. Ikke bare har han vært vitne til noen av historiens viktigste hendelser, han har også spilt en sentral rolle i dem. Vi følger Allans tidligere eskapader og hans utrolige innvirkning på historien, hvor han blant annet bidro til å oppfinne atombomben og ble gode venner med alt fra amerikanske presidenter til russiske tyranner",
