    "overview": "Brazil er en surrealistisk marerittvisjon av en “perfekt” framtid, der teknologien er enerådende. Alle blir overvåket av et hemmelig statlig byrå som skal hindre kjærligheten i å virke inn på effektiviteten. Jonathan Pryce og Robert De Niro har hovedrollene, sammen med Michael Palin og Bob Hoskins, i denne nifst svarte komedien i regi av det tidligere Monty Python-medlemmet Terry Gilliam.\r Når en dagdrømmende byråkrat intetanende roter seg borti en undergrunnssuperhelt og en vakker, mystisk kvinne, blir han det tragiske offeret for sine egne romantiske illusjoner.\r Denne uvanlige fantasifilmen blander bitende humor med skarp samfunnskommentar, og den gir en uforglemmelig titt på en fantastisk feig framtid.",
