    "awards": [],
    "overview": "I denne nærmest overjordisk vakre filmer følger vi to munker, en ung og en gammel, i arbeid, lek og læring. De bor i et ørlite flytende kloster, og gjennom årstidenes (og årenes) gang får også publikum en opplevelse av livets enorme verdi, tilværelsens skjønnhet og menneskets dumhet og ikke minst visdom.  Vi får se blendende vakre bilder av fjellandskap i skiftende årstider. Mer enn det, får vi se et forbløffende komplett spekter av menneskelige følelser. Her er alt med, og alt er ekte og riktig. Det er slett ikke verst på sirka hundre minutter, men Kim Ki-Duk får det til ved å konsentrere materien. Filmens tempo er også godt tilrettelagt for ettertanke, og denne ettertanken sitter igjen lenge etter at filmen er over.",
