    "overview": "I Hovedkvarteret - kontrollsenteret i den 11-årige Rileys hjerne - jobber de fem Følelsene veldig hardt, med den muntre optimisten \"Glede\" i spissen som har som oppgave å sørge for at Riley forblir lykkelig. \"Frykt\" tar seg av sikkerheten, \"Sinne\" sørger for at alt er rettferdig, og \"Avsky\" hindrer at Riley blir forgiftet, både fysisk og sosialt. \"Sorg\" er ikke helt sikkert på hva hennes rolle er, og ærlig talt er det ingen av de andre som er det heller.  Når Rileys familie flytter til en skremmende, ny by, er de fem Følelsene straks på saken og ivrige etter å hjelpe henne gjennom den vanskelige overgangen. Men når Glede og Sorg utilsiktet blir dratt dypt inn i Rileys sinn, og samtidig tar med seg noen av hennes kjerneminner, må Frykt, Sinne og Avsky motvillig ta kontrollen. Glede og Sorg må våge seg gjennom ukjente steder som Langtidsminne, Fantasiland, Abstrakte Tanker og Drømmeproduksjoner AS, i et desperat forsøk på å komme seg tilbake til Hovedkvarteret, og til Riley.",
