    "awards": [],
    "overview": "Da Walt Disneys historie om Alice og hennes fantastiske eventyr hadde kinopremiere i 1951, ble den ingen umiddelbar suksess. Det skulle faktisk ta nesten to tiår før Alice I Eventyrland fikk anerkjennelsen den fortjente - men siden den gang har filmen til gjengjeld befestet sin status som klassiker. Og det skulle bare mangle: Dette er en storslått tegnefilm lagt til en verden full av fantasi og musikk, hvor vi følger ungjenta Alice på hennes magiske reise inn i eventyrlandets fargerike verden. I jakten på den hvite kaninen blir ting stadig underligere og vår heltinne møter de merkeligste skapninger, som Den gale hattemakeren, Påskeharen, Trillebim og Trillebam, Filurkatten, Hjerterdame og mange, mange flere. Alice i eventyrland er full av vakre sanger og fantastisk animerte scener - rett og slett en tidløs klassiker, som hele familien kommer til å elske.",
    "poster": "posters/12092.jpg",
