    "overview": "Carl Fredrickson er en 78 år gammel, pensjonert ballongselger som endelig virkeliggjør sin livslange drøm om et storslått eventyr. Med hjelp fra tusenvis av ballonger fastbundet til huset sitt flyr han i vei på sitt livs reise til Sør-Amerika. Litt for sent oppdager Carl at hans verste mareritt, Russel – en overentusiastisk 8 år gammel speider, befinner seg på feil plass til feil tid – nemlig på Carls veranda! Verdens mest usannsynlige duo havner midt i et spennende eventyr i Sør-Amerika, på den hysteriske reisen får de noen nye venner: Hunn - den snakkende hunden og Kevin – den usedvanlige fuglen som ikke kan fly. Fanget i villmarken med Russel, oppdager Carl at de største eventyrene i livet ikke alltid blir som forventet!",
