    "awards": [],
    "overview": "Walt Disneys animerte klassiker Snehvit og de syv dvergene er hyllet over hele verden for sin tidløse historie, ikoniske karakterer og uforglemmelige musikk (\"Hei-Hå\"). Snehvit skinner som aldri før med en fantastisk ny digital restaurering. Den vakre og godhjertede prinsesse Snehvit sjarmerer alle dyrene i kongeriket, unntatt ett - hennes sjalu stemor, dronningen. Når det magiske speilet sier at Snehvit er den vakreste av dem alle, må hun flykte inn i skogen der hun blir venner med de syv dvergene - Brille, Prosit, Sinnataggen, Lystig, Blygen, Søvnig og Minsten. Men når dronningen lurer Snehvit med et forhekset eple, kan bare magien til ekte kjærlighet redde henne! Del denne elskede klassikeren med familien din og se Snehvit bli lykkelig alle sine dager, igjen og igjen.",
