    "overview": "Walt Disneys fantasifylte og magiske eventyr starter en natt i den snille dukkemakeren Gepettos verksted. På en hylle sitter hans tredukke Pinocchio stille, men så kommer Ønskefeen og vekker dukken til live - akkurat som Gepetto ønsket seg.  Men Pinocchio har mye å lære av livet før han kan regnes som en ekte gutt og får derfor hjelp av den kloke Timmi Gresshoppe, som skal lære ham hva som er rett og galt. For Timmi Gresshoppe blir det en krevende utfordring og forsøke å holde Pinocchio på rett vei...  Den to ganger Oscar®-belønnede (Beste sang og Beste filmmusikk (1940)) Pinocchio er Walt Disneys andre Klassiker og byr på en eventyrlig fortelling fylt med lengsel, drømmer, musikk og latter.",
