    "overview": "Ida er drømmedama. Hun er like hot som da hun var 20, har bein i nesa og kul jobb. Hun tar stort ansvar både hjemme og på jobben og er den som holder orden på livene deres. Mathias er drømmemannen. Han er morsom, rufsete kjekk og en fantastisk far. Dessverre er han også en rotekopp, vasker svarte sokker med hvitvask og blir aldri ferdig med å pusse opp badet. Dessuten kjøper han seilbåt uten å spørre først.  Ida og Mathias lever på hver sin planet mens de prøver å finne ut hva de egentlig ønsker seg i livet. For hva er egentlig lykken: Karriere? Nytt bad? En seilbåt? Sex med hvem du vil? Ny kjæreste? Eller er lykken faktisk det de allerede har?",
