    "awards": [],
    "overview": "Småen var Chaplins første langfilm, og er vel kanskje den mest rørende av alle filmene hans. I skildringen av den lille guttens fattigslige oppvekst ligger det trolig mye av Chaplins egen barndom fra London. Det som gjør mest inntrykk i filmen er imidlertid de intense og uttrykksfulle øyeblikkene mellom Chaplin og barnestjernen Jackie Coogan.\r Selve historien er enkel. En mor - hvis eneste synd var å bli mor - etterlater sitt barn som blir funnet av Charlie. Han tar rollen svært alvorlig, og snart er \"far\" og sønn involvert i en  blomstrende forretning som glassmakere. Småen knuser vinduene og Charlie reparerer dem. Etterhvert kommer barnevernet på sporet av den lille familien, og etter mye dramatikk innser  barnemoren at småen er hennes sønn. Hun har nå blitt rik og vil ha sitt fortapte barn tilbake, og utlover en stor belønning. Plutselig er alle ute etter å skille Landstrykeren og småen.",
    "poster": "posters/10098.jpg",
