    "overview": "Diktatoren er en kraftfull film, med en mengde komiske opptrinn, som når Tomanias maktgale diktator Adenoid Hynkel snakker seg så varm at han ikke bare må kjøle stemmebåndene, men også tømme vann nedover buksene sine. Filmen er også meget vakkert fotografert, og scenen hvor Hynkel leker med jordkloden før han til slutt punkterer den er blitt klassisk. I Diktatoren gjør Chaplin en parodi på Hitler, hans retorikk, hans manerer og hans innbilte stolthet. Den generelle amerikanske holdningen på den tiden var at Hitler mer var en klovn man måtte le av enn en plage man burde frykte. Det var først senere det gikk opp for amerikanerne hvilken trussel han faktisk var.",
