    "awards": [],
    "overview": "Fra mennene bak \"Fargo\", \"O Brother, Where Art Thou?\" og \"Intolerable Cruelty\" kommer en kompleks og brutal visjon av gangstere i USA.  Filmen foregår i deres glansdager under forbudstiden og inneholder et fengslende galleri av mordere og svindlere. Leo er den vennlige, irske gangsteren og politiske bossen som hersker over en by i det østlige USA, med antihelten Tom som sin betrodde nestkommanderende og rådgiver. Men deres herredømme blir utfordret av en streber av en italiensk underboss, Johnny Casper, og hans nådeløse hjelper Eddie Dane. Samtidig som Tom prøver å opprettholde freden, blir det personlig mellom ham og Leo på grunn av en kvinne, og han står midt i en maktkamp.  \"Miller's Crossing\" drives fram av action, fantastisk filmfotografi, mengder av svart humor og sjokkerende vold. Den intense historien går på en stram line der ingenting er helt som det ser ut til.",
