    "overview": "En mann, en kvinne og en kanin i et trekantdrama I en Hollywood-ghetto i 1940-årene blir en hardbarket detektiv, Eddie, dratt inn i en intrige med en sprø tegneseriefigur, Roger. Ubevisst kommer Eddie til å legge skylden for et mord på Roger, og for å renske opp i misforståelsene tar han opp jakten på andre mistenkte. I en fantastisk blanding av spille- og tegnefilm havner hovedpersonen, Roger Rabbit, opp i mye trøbbel. Han kone bedrar ham (med et menneske!) og selv blir han beskyldt for mord. Roger Rabbit, som egentlig er en kjent tegnefilmstjerne, blir nødt til å ta kontakt med en privatdetektiv i Bob Hoskins skikkelse, altså et menneske. Privatdetektiven er ikke den sobre, elegante utgaven av arten, men en forsoffen, alkoholisert «private eye» som selv har store problemer. Filmen er den første som virkelig klarer å blande ekte skuespillere sammen med tegneseriefigurer på en troverdig måte",
