    "overview": "Det er depresjon i Amerika, og dagdriverne Clyde Barrow og Bonnie Parker havner på skråplanet – sammen. De er like ville etter farlige eventyr som etter hverandre, og legger ut på en reise som blir stadig mer preget av vold. Etter hvert går det opp for oss at også de to kan bli skadet – og vi frykter at de til og med kan bli drept.  De to hovedrolleinnehaverne gir strålende prestasjoner og får solid skuespillerstøtte av Michael J. Pollard, Gene Hackman og Estelle Parsons. Sistnevnte vant en Oscar-pris for beste kvinnelige birolle i 1967. Regissør Arthur Penn sørger for at stemningen i filmen er røff, men ikke ondskapsfull. Filmen fortsetter å imponere publikum også i dag – spesielt på grunn av filmfotograf Burnett Guffeys (som skaffet filmen dens andre Oscar) og klipper Dede Allens innsats. Flere generasjoner etter at den ble laget er den fremdeles en forrykende og spennende opplevelse.",
