    "awards": [],
    "overview": "Bambi er fortellingen om den unge hjortekalven som en dag skal bli skogens fyrste. Veien dit er lang - det er mye han må lære, og mye han må forstå. Bambi får heldigvis god hjelp av vennene Trampe, Ugle og det blyge stinkdyret Blomst, men den praktfulle pappaen hans er nok den eneste som kan redde Bambi fra alle farene som lurer i skogen.  Disney lot seg inspirere av Østens billedkunst da han skapt denne kraftfulle og poetiske tegnefilmen. I Bambi er det nemlig ikke bare dyrene som lever- hele naturen har faktisk fått liv. Filmen er en fantastisk klassiker og et garantert minne for livet, et vakkert familieeventyr som ble Oscar-nominert flere ganger og var Walt Disneys personlige favoritt. Da The American Film Institute i 2008 kåret tidenes beste amerikanske filmer, endte Bambi på en tredjeplass i klassen for animasjon.",
