    "overview": "Den klassiske fortelling om den lille sirkuselefanten Dumbo er Disneys fjerde tegnede langfilm. \"Dumbo\" er et hjertevarmt eventyr med masser av sjarm og nydelige sanger.  Dumbo blir født med to aldeles for store ører og han blir mobbet og ledd av. Så dukker musen Timmi opp, og han blir Dumbos beste venn. Timmi prøver å lære Dumbo noen fine sirkuskunster, men de store ørene er i veien hele tiden. Plutselig en dag oppdager Dumbo at han kan noe som ingen andre kan. Han kan fly!  Disneys klassike film om Dumbo er en tidløs fortelling om en liten modig elefant med et par aldeles for store ører... men med et enda større hjerte.",
